select s.name, s.version_no, s.status, s.access_tier, s.readiness_status,
       (select count(*) from mock_exam_set_items i where i.exam_set_id = s.id) as items,
       (select count(*) from mock_exam_set_items i join problems p on p.id = i.problem_id where i.exam_set_id = s.id and p.published_version_id is distinct from i.problem_version_id) as stale_items
  from mock_exam_sets s where s.set_group_id in ('6f4473a5-0b9c-47ab-a0e4-1fdbb7c07c4b', '34569222-4ad0-4fc0-8c04-be069c35cf10', '0952b774-6156-4d09-a5fa-fb4943b20dac', '65efce5c-39ff-44dc-a868-c87e707027ec', '591a9abd-bf5d-4387-9d79-a138ef814967', '43bb7a0c-7010-4930-8da3-e5e168ade116', '11cc6603-0671-4ef7-93b7-02b2011294d4', 'f981bddb-2e31-4bf0-bdc6-da8f68582ed0', '1f165064-c082-4d5e-bd17-0a0f3863e6f8', 'c21312d0-2b9a-4ee5-8196-e98aa5f2fc17', '8b284820-f11f-43ad-a33b-816df5479f26', '834d3096-cb62-42c4-be52-c6a76bc88e81', '6a25f2b5-92a6-48a3-a4b7-8a2c420f8e19', 'a57a7d5e-850c-43f2-991d-785450e72018', 'f99e778c-3b8f-4e4a-8116-c5bc29a338a9') and s.status in ('published', 'draft') order by s.name;
